---@class ItemsConfig
local ItemsConfig = T(Global, "ItemsConfig")
---@class ShopItemCfg
---@field id number
---@field meta number

---@type ShopItemCfg[]
local Items = {}
---@type ShopItemCfg[]
local Blocks = {}
local CheckItems = {}

function ItemsConfig:init()
    local blockConfig = FileUtil.getGameConfigFromCsv("CreativeBlock.csv", 1)
    for i, v in pairs(blockConfig) do
        ---@type ShopItemCfg
        local item = {
            id = tonumber(v.ItemId),
            meta = tonumber(v.subItemId),
            sort = tonumber(v.Id),
        }
        table.insert(Blocks, item)
        CheckItems[item.id .. "#" .. item.meta] = true
    end
    table.sort(Blocks, function(a, b)
        return a.sort < b.sort
    end)

    local itemConfig = FileUtil.getGameConfigFromCsv("CreativeItem.csv", 1)
    for _, v in pairs(itemConfig) do
        ---@type ShopItemCfg
        local item = {
            id = tonumber(v.ItemId),
            meta = tonumber(v.subItemId),
            sort = tonumber(v.Id),
        }
        table.insert(Items, item)
        CheckItems[item.id .. "#" .. item.meta] = true
    end
    table.sort(Items, function(a, b)
        return a.sort < b.sort
    end)
end

---@return ShopItemCfg[]
function ItemsConfig:getItems()
    return Items
end

---@return ShopItemCfg[]
function ItemsConfig:getBlocks()
    return Blocks
end

---@return ShopItemCfg[]
function ItemsConfig:getCfgs(type)
    if type == Define.ShopItemType.Block then
        return Blocks
    elseif type == Define.ShopItemType.Item then
        return Items
    end
    return nil
end

function ItemsConfig:checkGoodsInfoEnable(id, meta)
    return CheckItems[id .. "#" .. meta] or false
end

ItemsConfig:init()

return ItemsConfig